const catalogs: PublishedCatalog[] = ["openai-api-fundamentals", "agent-foundations"].map((id) => ({
  course: { id, title: id, summary: "Synthetic", level: "Basic", durationMinutes: 1, moduleIds: [`${id}-module`] },
